#!/usr/bin/env node
import { writeFileSync } from "node:fs";
import { join } from "node:path";

import { modelsDevCachePath, readCachedModelIndex } from "@luthfisolahudin/9router-integrations-catalog";

import { excluded, inventoryRows, loadAll, unmeasured } from "../lib/packs.ts";

const write = process.argv.includes("--write");
const cached = readCachedModelIndex(modelsDevCachePath());
const loaded = loadAll(process.cwd(), cached === undefined ? {} : { modelsDev: cached });
const lines: string[] = [
	"# Provider inventory",
	"",
	"Generated by `task report`. Do not edit by hand.",
	"",
	"`limits-src` and `effort-src` are provenance: `catalog` and `measured` are facts,",
	"`curated` comes from a vendor document, and `default` is a guess. See `docs/EVIDENCE.md`.",
	"",
];

for (const entry of loaded) {
	lines.push(`## ${entry.pack.name} (\`${entry.pack.id}\`)`, "");
	lines.push(`- base: \`${entry.pack.baseUrl}\``);
	lines.push(`- discovery: \`${entry.pack.discovery.path}\`${entry.fixture === undefined ? " (no fixture)" : ""}`);
	lines.push(`- source: ${entry.source}, ${entry.models.length} model(s)`, "");
	lines.push("| id | name | context | max-out | cost/1M | input | reasoning | format | wire-effort | limits-src | effort-src |");
	lines.push("|---|---|---|---|---|---|---|---|---|---|---|");
	for (const row of inventoryRows(entry.models)) lines.push(`| ${row.join(" | ")} |`);

	const hidden = excluded(entry.models);
	if (hidden.length > 0) {
		lines.push("", `Excluded: ${hidden.map((item) => `\`${item.id}\` (${item.reason})`).join(", ")}`);
	}
	const nothing = unmeasured(entry.models);
	if (nothing.length > 0) {
		lines.push("", `Unmeasured reasoning models (visible, no effort menu): ${nothing.map((id) => `\`${id}\``).join(", ")}`);
	}
	lines.push("");
}

const markdown = `${lines.join("\n").trimEnd()}\n`;
if (write) {
	const path = join(process.cwd(), "docs", "PROVIDERS.md");
	writeFileSync(path, markdown);
	console.log(`wrote docs/PROVIDERS.md (${markdown.split("\n").length} lines)`);
} else {
	process.stdout.write(markdown);
}
